#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-08

# scripts/lib/semver.sh
#
# strict-mode: opt-out sourced library — `set -euo pipefail` here would leak into
# every caller's shell. bin/git-hooks/pre-push in particular is not written to
# survive `set -e`, so setting it from a sourced file would change unrelated
# behaviour in a git hook. Each function below is total: it reads its arguments,
# runs one pipeline, and returns a status. Callers keep their own options.
#
# Semver-correct comparison for shell callers, plus regex escaping for the
# places that drop a version into a pattern.
#
# WHY THIS EXISTS
# ---------------
# `sort -V` is not semver. Semver 2.0.0 says a prerelease has LOWER precedence
# than the release it precedes, but `sort -V` puts it higher, because it reads
# the suffix as extra version content rather than as a prerelease marker:
#
#     printf '10.0.0\n10.0.0-alpha.1\n' | sort -V | tail -1   ->  10.0.0-alpha.1
#
# Four callers used that as "the higher version", so every one of them would
# have called 10.0.0-alpha.1 newer than 10.0.0 during the v10 alpha train.
#
# THE FIX
# -------
# `sort -V` implements Debian version ordering, where `~` sorts BEFORE the empty
# string. Semver's `-` means exactly what Debian's `~` means, so translating one
# to the other before sorting gives correct precedence with no new dependency
# and no version parser to get wrong.
#
# Verified on both implementations that actually run this repo, same six pairs,
# identical results (2026-08-08):
#
#     sort (GNU coreutils) 9.7   <- ubuntu-latest, CI
#     sort 2.3-Apple (199)       <- macOS, local hooks
#
# tests/unit/test-semver-compare.sh pins the table on whichever platform runs it,
# so a future coreutils change that breaks `~` ordering fails the suite rather
# than silently mis-ranking a release.

# _semver_to_debian <version>
# Semver prerelease marker -> Debian's "sorts before nothing" marker.
# Only the FIRST '-' is the prerelease separator; later ones are part of the
# identifier (1.0.0-alpha-1) and must be left alone.
_semver_to_debian() {
    case "$1" in
        *-*) printf '%s~%s\n' "${1%%-*}" "${1#*-}" ;;
        *)   printf '%s\n' "$1" ;;
    esac
}

# semver_max <a> <b> — print whichever has higher semver precedence.
# Equal inputs print that value.
semver_max() {
    local a b winner
    a="$(_semver_to_debian "$1")"
    b="$(_semver_to_debian "$2")"
    winner="$(printf '%s\n%s\n' "$a" "$b" | sort -V | tail -1)"
    # Map back by identity rather than by substitution: a '~' could only have
    # come from the transform, but returning the original string avoids doubt.
    if [ "$winner" = "$a" ]; then printf '%s\n' "$1"; else printf '%s\n' "$2"; fi
}

# semver_lt <a> <b> — true when a has strictly lower precedence than b.
semver_lt() {
    [ "$1" != "$2" ] && [ "$(semver_max "$1" "$2")" = "$2" ]
}

# semver_gt <a> <b> — true when a has strictly higher precedence than b.
semver_gt() {
    [ "$1" != "$2" ] && [ "$(semver_max "$1" "$2")" = "$1" ]
}

# semver_core <version> — strip the prerelease and build-metadata parts.
# 10.0.0-alpha.1 -> 10.0.0 ; 1.0.0+build.5 -> 1.0.0
semver_core() {
    local v="${1%%+*}"
    printf '%s\n' "${v%%-*}"
}

# semver_is_prerelease <version> — true when a prerelease part is present.
semver_is_prerelease() {
    case "${1%%+*}" in *-*) return 0 ;; *) return 1 ;; esac
}

# semver_regex_escape <version> — quote every ERE metacharacter.
#
# A version is data, not a pattern. Interpolated raw, `10.0.0` matches `10x0x0`,
# and build metadata like `1.0.0+build.5` carries a `+` that changes the meaning
# of the preceding atom outright.
#
# Deliberately no sed. Escaping metacharacters with a bracket expression means
# writing a pattern whose own metacharacters need escaping, and BSD sed rejected
# two different spellings of it ("unbalanced brackets") before this. A substring
# test has no pattern syntax at all, so there is nothing to get wrong, and it
# runs no subprocess.
semver_regex_escape() {
    local s="$1" out="" c i
    local meta='].[*^$+?(){}|\'
    for (( i = 0; i < ${#s}; i++ )); do
        c="${s:i:1}"
        case "$meta" in
            *"$c"*) out="${out}\\${c}" ;;
            *)      out="${out}${c}" ;;
        esac
    done
    printf '%s' "$out"
}
